func testAccResourceAutoF5XCProxyConfig_withProxyPolicy(name, policyName, namespace string, enablePolicy bool) string {
	// When policy is enabled, use the provided namespace (app namespace) for both
	// to avoid namespace conflicts with DrpHttpConnect policies
	proxyNamespace := namespace
	policyNamespace := namespace
	proxyPolicyChoice := "no_forward_proxy_policy = true"
	if enablePolicy {
		proxyPolicyChoice = fmt.Sprintf(`active_forward_proxy_policies = {
      forward_proxy_policies = [{
        name      = %q
        namespace = %q
      }]
    }`, policyName, policyNamespace)
	}

	return fmt.Sprintf(`
resource "f5xc_forward_proxy_policy" "policy" {
  name      = %q
  namespace = %q

  proxy_choice = {
    drp_http_connect = true
  }

  rule_choice = {
    allow_all = true
  }
}

resource "f5xc_proxy" "test" {
  name      = %q
  namespace = %q

  proxy_choice = {
    http_proxy = {
      http_https_choice = {
        enable_http = true
      }
    }
  }

  site_choice = {
    do_not_advertise = true
  }

  network_choice = {
    site_local_network = true
  }

  proxy_policy_choice = {
    %s
  }

  tls_interception_choice = {
    no_interception = true
  }

  depends_on = [f5xc_forward_proxy_policy.policy]
}
`, policyName, policyNamespace, name, proxyNamespace, proxyPolicyChoice)
}
